"""Regression test for FND-000002 - SQL injection in find_trades_by_account."""

from ledger import db


def conn():
    return db.bootstrap(db.connect())


def test_quote_in_account_is_data_not_syntax():
    assert db.find_trades_by_account(conn(), "' OR '1'='1") == []


def test_legitimate_quote_still_matches_trades():
    rows = db.find_trades_by_account(conn(), "O'Brien Holdings")
    assert len(rows) == 1 and rows[0]["symbol"] == "MSFT"
